mapper.select:
SELECT i.*,t.task_code,t.task_name FROM srv_service_issue i
JOIN srv_inspection_task t ON t.tenant_id=i.tenant_id AND t.id=i.task_id AND t.deleted=b'0'
WHERE i.tenant_id=#{query.tenantId} AND i.responsible_user_id=#{query.actorId}
  AND i.deleted=b'0' AND i.status_code!='CLOSED'


        AND t.project_id IN #{id}

    AND 1=0

ORDER BY i.due_at,i.id LIMIT #{query.limit}
